(() => {
  'use strict';
  const data=window.OMNIECHO_INVESTIGATION, prior=window.OmniResults, registry=window.OMNIALE_DATA;
  if(!data||!prior||!registry)return;
  const task=data.case, key=task.key;
  task.seq=Math.max(...registry.cases.map(c=>Number(c.seq)||0))+1;
  if(!registry.cases.some(c=>c.key===key))registry.cases.push(task);
  const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const J=v=>E(JSON.stringify(v));
  const N=n=>n.toFixed(4);
  const names={direction:'方向',localization3d:'方向与距离',camera_rotation:'相机转动 / 转向关系',motion:'运动方向'};
  const sources={camera:'相机',S1:'报警声',S2:'塑料摩擦声',S3:'钥匙声'};
  const assetMap={"omniecho-investigation/candidate/incident.mp4": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/omniecho-investigation-v1-20261118/71d0ddbff4b2c53ead6c-incident.mp4", "omniecho-investigation/case1__sol_01/evidence/E736373124dbb4125.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/omniecho-investigation-v1-20261118/c0181c7a75047b7fb3ae-E736373124dbb4125.mkv", "omniecho-investigation/case1__sol_01/evidence/Eaf5286d3f13c40c4.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/omniecho-investigation-v1-20261118/2503327a55653b3b0430-Eaf5286d3f13c40c4.mkv", "omniecho-investigation/case1__sol_01/evidence/Ec3554e97ebc548ea.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/omniecho-investigation-v1-20261118/92175f1e5d43b238c984-Ec3554e97ebc548ea.mkv", "omniecho-investigation/case1__sol_01/evidence/Ec5b5d7d616aa4a05.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/omniecho-investigation-v1-20261118/1c86d29543c6531de714-Ec5b5d7d616aa4a05.mkv", "omniecho-investigation/case1__luna_01/evidence/Ee463ebd1e9274d9f.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/omniecho-investigation-v1-20261118/7c4b7d7deeb5a4781af5-Ee463ebd1e9274d9f.mkv", "case26-current/6-1-sol/submission/preview.mp4": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/case26-av-music-v2-20261118/f5f8f0389445671a36ac-preview.mp4", "case26-current/6-1-sol/submission/repair.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/case26-av-music-v2-20261118/d855371e68d12015fd72-repair.mkv", "case26-current/6-1-sol/submission/restored.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/case26-av-music-v2-20261118/5fcd8c0af0fb4dd6e722-restored.mkv", "case26-current/6-1-sol/submission/restored_av.mp4": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/case26-av-music-v2-20261118/f929cfc4241212df0467-restored_av.mp4", "case26-current/6-luna/submission/preview.mp4": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/case26-av-music-v2-20261118/49cf92bb8b70667b1374-preview.mp4", "case26-current/6-luna/submission/repair.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/case26-av-music-v2-20261118/77023a6f8004c2287a5d-repair.mkv", "case26-current/6-luna/submission/restored.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/case26-av-music-v2-20261118/a73718eba274152cf399-restored.mkv", "case26-current/6-luna/submission/restored_av.mp4": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/case26-av-music-v2-20261118/581a9d27689c1083d7c5-restored_av.mp4", "case26-current/candidate/input/damaged.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/case26-v3-20261111/8602b0e4eed47b98-1794392637-damaged.mkv", "case26-current/candidate/input/damaged_av.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/case26-av-music-v2-20261118/b3e77c07c8e501a9c879-damaged_av.mkv", "omniecho-investigation/case1__astra_xhigh_unlimited_20261119_newkey/evidence/E5d3506f851304c41.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/untagged-d3f4a41459b93c68de60/78abef16262a703c499c-E5d3506f851304c41.mkv", "case26-current/6-astra/submission/repair.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/untagged-d3f4a41459b93c68de60/dbe44eb86fa1ec84c2be-repair.mkv", "case26-current/6-astra/submission/restored.mkv": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/untagged-d3f4a41459b93c68de60/fd632744f531abcee96b-restored.mkv", "case26-current/6-astra/submission/restored_av.mp4": "https://github.com/NanXiang-git/OmniALE_v2/releases/download/untagged-d3f4a41459b93c68de60/44cda296219a9207dbd5-restored_av.mp4"};const asset=p=>assetMap[p]||p;
const link=(url,label)=>`<a href="${E(asset(url))}" target="_blank" rel="noopener">${E(label)} ↗</a>`;
  const first=data.models[0];
  window.OMNIALE_RESULTS[key]={key,model:first.model,effort:first.effort,total:first.grade.score,verified:first.grade.score,
    accepted:false,gradeStatus:'complete',pendingPoints:0,automatic:null,judge:null,automaticMax:100,judgeMax:0,
    rows:[{maximum:100,points:first.grade.score}],artifacts:first.artifacts,reports:[],seconds:first.seconds,timedOut:false,
    comparisons:data.models.slice(1).map(m=>({model:m.model,total:m.grade.score,verified:m.grade.score})),integrity:{passed:true}};
  let selected=first.key, section='answer';
  function maturity(){return `<h3>当前成熟度：可执行的单样本开发题</h3><p>已经完成素材追溯、题包、隔离执行、封存交付和冻结规则评分；本样本已经曝光，后续应留在开发集。每模型的单次运行不足以形成模型能力排名；时间预算不同需一并考虑。</p><ol>
    <li><b>先校准声学与真值。</b>请独立复核四通道顺序、坐标轴、镜头与世界坐标、旋转符号和声源对应，再抽查原标注。当前错误不能直接归因于模型能力，也不能把低分当成题目成熟的证据。</li>
    <li><b>加强 agent 评测。</b>现在 E 只检查来源与时间覆盖，D 检查交付；完整视频也能覆盖全部证据。需为下一版本预先定义证据是否实际支持结论、证据定位和报告复核效率等验收标准，再冻结评分；不追溯改判本轮。</li>
    <li><b>补浏览器验收。</b>已做源码、引用和媒体解码检查；真实浏览器离线打开、播放、跳转及布局仍待验收。</li>
    <li><b>扩成独立题集并校准。</b>建议先选 10–20 个不同原视频做开发校准，再建设 30–50 个或更多分层样本；按场景/源视频划分开发和测试，重复运行并分析稳定性后锁定阈值。这些是建议规模，尚未完成。</li></ol><p class="oe-note">原始公开数据可能已进入训练语料；断网和隐藏参考只减少推理时取巧，无法排除训练污染。当前为本地工具辅助音频分析轨道，不是模型原生音频输入轨道。</p>`;}
  function answer(m){return `<h3>${E(m.model)} · 冻结调查报告</h3><p>Agent 自行选择分析顺序、抽帧与音频空间分析，调用工具导出证据，生成 HTML 与 JSON，最后验证并封存。三个声源类别和待查字段由题面提供，声源类别识别不计入本轮成绩。</p><div class="oe-links">${link(m.links.report,'打开完整模型报告')}${link(`omniecho-investigation/${m.key}/findings.json`,'结构化答卷')}${link(`omniecho-investigation/${m.key}/evidence_manifest.json`,'证据回执')}</div><p class="oe-note">以下为实际导出的双声道播放预览，仅供浏览；空间分析与证据原件保留四通道。报告中的陈述是模型答卷，不等于原始真值。</p>${m.exports.map((x,i)=>{const base=`omniecho-investigation/${m.key}/`; const preview=x.preview_path;return `<details ${i===0?'open':''}><summary>证据 ${i+1} · ${x.start_s.toFixed(2)}–${x.end_s.toFixed(2)} 秒</summary><video controls playsinline preload="none" src="${asset(base+preview)}" aria-label="${E(m.model)} 证据 ${i+1}"></video><p>${link(base+x.path,'四通道原件')} · ${link(base+preview,'双声道预览')}</p></details>`}).join('')}<p class="oe-note">完整报告在独立页面打开，以保留模型原始布局、锚点和交互。当前页不改写答卷内容。</p>`;}
  function scores(m){const g=m.grade;return `<h3>评分与扣分 · ${N(g.score)} / 100</h3><p><b>S = 100 × F × (0.70 + 0.20E + 0.10D)</b>。本轮 F=${g.original_fact_correct}/18，E=${g.E}，D=${g.D}。</p><div class="oe-warning">本模型 E=${g.E}、D=${g.D}；仅当二者均为 1 时，最终分数等于事实正确率。证据来源可追溯不代表其语义足以支持结论；交付检查也不等于真实浏览器播放验收。</div><div class="oe-scroll"><table><thead><tr><th>原标注类别</th><th>正确 / 总数</th><th>失分事实</th></tr></thead><tbody>${Object.entries(g.breakdown).map(([k,v])=>`<tr><td>${names[k]}</td><td>${v.correct} / ${v.total}</td><td>${v.total-v.correct}</td></tr>`).join('')}</tbody></table></div><p>通过需 S≥80、F≥0.8、E≥0.9、D=1，且每个声源至少有一条正确且具备可播放证据的事实。${g.task_pass?'本模型达到全部通过条件。':'本模型未达到全部通过条件，具体见评分记录。'}</p><p class="oe-note">按原基准口径：八方向精确匹配；转向精确且角度误差≤45°；定位方向精确且距离误差≤2米；yes/no 精确匹配。18 个原始事实合并为 17 条公开记录，评分仍逐事实计算。</p><h3>18 个事实：原标注与模型答案</h3><p class="oe-note">参考仅在评后展示；模型执行环境未挂载隐藏真值。JSON 字段保留原值，避免翻译改变判分含义。</p><div class="oe-scroll"><table class="oe-facts"><thead><tr><th>事实 / 记录</th><th>对象 · 时间 · 坐标</th><th>类别</th><th>原标注参考</th><th>模型答案</th><th>判定</th></tr></thead><tbody>${g.atoms.map(a=>{const r=data.coverage.records.find(r=>r.record_id===a.record_id);return `<tr><td>${a.atom_id} / ${a.record_id}<small>原 JSONL 第 ${a.original_jsonl_line} 行</small></td><td>${sources[a.source_id]}<small>${r.time_s??r.interval_s?.join('–')} 秒 · ${E(r.coordinate_frame)}</small></td><td>${names[a.category]}</td><td><code>${J(a.reference)}</code></td><td><code>${J(a.prediction)}</code></td><td class="${a.correct?'oe-pass':'oe-fail'}">${a.correct?'正确':'错误'}</td></tr>`}).join('')}</tbody></table></div><p>${link(m.links.grade,'完整冻结评分')}</p>`;}
  function records(m){return `<h3>运行与来源</h3><p>${E(m.model)} / xhigh；${E(m.timeBudget||'35 分钟上限')}，实际 ${(m.seconds/60).toFixed(2)} 分钟。单次尝试，${m.apiCalls} 次 API 调用，${m.apiErrors} 次 API 错误。模型通过本地 Python、FFmpeg 和图像工具处理音视频，没有原生音频输入。</p><p>WSL + bubblewrap 隔离，输入只读、公网关闭、隐藏真值与其他答卷不可见。宿主代理调用模型服务，接口返回模型名与请求一致；第三方网关背后的模型权重未独立认证。</p><div class="oe-links">${Object.entries({run:'运行原始记录',trace:'宿主工具轨迹',review:'交付复核记录',grade:'评分 JSON',final:'最终回复'}).map(([k,v])=>link(m.links[k],v)).join('')}</div><h3>素材和真值从哪里来</h3><p>${link('https://huggingface.co/datasets/PKU-VaLuE-Lab/OmniEchoBench','OmniEchoBench 数据集')} 中的 <code>OmniEchoBench-QA/videos/vid_0095.mp4</code>（S1107），37.333333 秒、1920×1080、48kHz 四通道。使用原视频与原 QA 答案，没有合成新的声音事件。</p><p>数据版本 <code>5c85a02fd612f22c26c62f2fad883a46c4685213</code>。原 QA 零基索引 89–108 中，排除结束于 37.5 秒、超过实测片长的 106 与 108；剩余 18 个事实。由完整原答案解析真值，保留原方向、角度和距离容差。调查流程、证据回执与报告交付是我们新增的 agent 包装。</p><p class="oe-note">因直连下载不稳定，实际使用 HF 镜像；原媒体 SHA256 与冻结 LFS 清单匹配，并已完整解码。原媒体 SHA256：<code>71d0ddbff4b2c53ead6c93c52f2da8a68d9d628fadfd191402b7d7780b3068fd</code>。这能确认文件来源和完整性，不能替代标注正确性复核。上游 README 声明 CC BY-NC-SA 4.0。</p><div class="oe-links">${link('https://arxiv.org/html/2609.23407v2','论文')}${link('https://github.com/PKU-VaLuE-Lab/OmniEcho/tree/1f3696d637027edc673db81629aed1586e4c1983','上游代码')}${link('omniecho-investigation/asset_provenance.json','素材来源与哈希')}${link('omniecho-investigation/TRIAL_PROTOCOL.md','试跑协议')}${link('omniecho-investigation/trial_freeze.json','冻结清单')}</div><h3>全部冻结交付物</h3><div class="oe-scroll"><table><thead><tr><th>文件</th><th>大小</th><th>查看</th></tr></thead><tbody>${m.artifacts.map(f=>`<tr><td>${E(f.name)}</td><td>${(f.bytes/1e6).toFixed(2)} MB</td><td>${link(f.url,'打开 / 下载')}</td></tr>`).join('')}</tbody></table></div>`;}
  function render(c,r,target){
    if(c.key!==key)return prior.render(c,r,target);
    const m=data.models.find(m=>m.key===selected);
    target.querySelectorAll('video,audio').forEach(el=>el.pause());
    target.innerHTML=`<section class="oe" data-omniecho><div class="oe-top"><h2>多声源调查 · ${data.models.length} 组结果</h2><span class="oe-chip">开发试跑 / 单个原视频</span></div><p>同题、同输入、同冻结规则；均为 xhigh，时间预算见各行。当前结果用于检查任务与评测流程，预算差异限制直接比较。</p><div class="oe-scroll"><table data-oe-models><thead><tr><th>模型</th><th>事实正确</th><th>E / D</th><th>得分 / 100</th><th>实际用时</th><th>状态 / 答卷</th></tr></thead><tbody>${data.models.map(x=>`<tr class="${m.key===x.key?'oe-selected':''}"><td>${x.model}<small>xhigh · ${E(x.timeBudget||'35 分钟上限')}</small></td><td>${x.grade.original_fact_correct} / 18</td><td>${x.grade.E} / ${x.grade.D}</td><td><b>${N(x.grade.score)}</b></td><td>${(x.seconds/60).toFixed(2)} 分钟</td><td><span class="${x.grade.task_pass?'oe-pass':'oe-fail'}">${x.grade.task_pass?'通过':'未通过'}</span><br><button class="button" data-oe-model="${x.key}" aria-pressed="${x.key===m.key}">${x.key===m.key?'正在查看':'查看答卷'}</button></td></tr>`).join('')}</tbody></table></div><div class="oe-tabs" role="tablist" aria-label="调查结果分区">${[['answer','答卷与证据'],['scores','评分明细'],['records','交付与来源'],['maturity','距离成熟还差什么']].map(([k,v])=>`<button id="oe-tab-${k}" role="tab" aria-controls="oe-content" tabindex="${k===section?0:-1}" aria-selected="${k===section}" data-oe-section="${k}">${v}</button>`).join('')}</div><div id="oe-content" role="tabpanel" aria-labelledby="oe-tab-${section}">${section==='answer'?answer(m):section==='scores'?scores(m):section==='records'?records(m):maturity()}</div></section>`;
    target.querySelectorAll('[data-oe-model]').forEach(b=>b.onclick=()=>{selected=b.dataset.oeModel;render(c,r,target);target.querySelector(`[data-oe-model="${selected}"]`).focus({preventScroll:true});});
    const keys=['answer','scores','records','maturity'];
    target.querySelectorAll('[data-oe-section]').forEach(b=>{const go=s=>{section=s;render(c,r,target);target.querySelector(`#oe-tab-${section}`).focus({preventScroll:true});};b.onclick=()=>go(b.dataset.oeSection);b.onkeydown=e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();e.stopPropagation();go(keys[e.key==='Home'?0:e.key==='End'?3:(keys.indexOf(section)+(e.key==='ArrowRight'?1:3))%4]);};});
    target.querySelectorAll('video,audio').forEach(el=>el.addEventListener('play',()=>target.querySelectorAll('video,audio').forEach(o=>{if(o!==el)o.pause();})));
  }
  window.OmniResults=Object.freeze({...prior,render,overview(cases,results,target){prior.overview(cases,results,target);const row=target.querySelector(`a[href="#${key}/results"]`)?.closest('tr');if(row){row.classList.add('oe-overview');row.innerHTML=`<td><a href="#${key}/results"><b>多声源事件调查与证据报告</b><small>开发试跑 · ${data.models.length} 组 · 单样本</small></a></td><td colspan="4">${data.models.map(m=>`${m.model} · <b>${N(m.grade.score)}</b> / 100 · ${m.grade.original_fact_correct}/18 个事实`).join('<br>')}</td><td>${data.models.filter(m=>m.grade.task_pass).length} 组通过<br>成熟度待校准</td><td><a class="button" href="#${key}/results">查看 ↗</a></td>`;}}});
})();
